return items.map(item => {
  // Clean and parse the OpenAI JSON string
  const cleanContent = (item.json.message?.content || "")
    .replace(/```json\n?/gi, "")
    .replace(/```/g, "")
    .trim();

  let parsed;
  try {
    parsed = JSON.parse(cleanContent);
  } catch (e) {
    parsed = {
      caption: "Default caption",
      platform_variations: {
        instagram: "Default Instagram post",
        facebook: "Default Facebook post",
        google_my_business: "Default GMB post"
      }
    };
  }

  return {
    json: {
      caption: parsed.caption,
      instagram_caption: parsed.platform_variations.instagram,
      facebook_caption: parsed.platform_variations.facebook,
      gmb_caption: parsed.platform_variations.google_my_business
    }
  };
});

const inputs = $input.all();

// ====== CONFIG ======
const ACCOUNT_IDS = [
  "6893f5a15e610eadc31ce823_RMmf289hB5J7LjtJJLYt_5785078155395707813", // Google (Location)
  "6893f54d5c4cf8633d4e3dd8_RMmf289hB5J7LjtJJLYt_360456737156031_page", // Facebook Page
  "6893f586c9b9253d0eeba628_RMmf289hB5J7LjtJJLYt_17841466410443185"    // Instagram Profile
];
const USER_ID = "lWZjS6ppoRL7w9v2r1VM";
const SCHEDULE_HOUR = 10;  
const SCHEDULE_MIN  = 0;
// =====================

// --- Helpers ---
function safeString(v, fallback = "") {
  return (typeof v === "string" ? v : fallback);
}

function stripEmojis(str) {
  return safeString(str).replace(/\p{Extended_Pictographic}|\p{Emoji_Presentation}/gu, "");
}

function baseNameFromUrl(u) {
  try {
    const p = new URL(u).pathname;
    const leaf = p.split("/").pop() || "post";
    return leaf;
  } catch {
    return "post";
  }
}

function extFromNameOrUrl(nameOrUrl) {
  const s = safeString(nameOrUrl).toLowerCase();
  const m = s.match(/\.([a-z0-9]+)(?:$|\?)/);
  return m ? m[1] : "";
}

function mimeFromNameOrUrl(nameOrUrl) {
  const ext = extFromNameOrUrl(nameOrUrl);
  if (ext === "png") return "image/png";
  if (ext === "gif") return "image/gif";
  if (ext === "webp") return "image/webp";
  if (ext === "mp4") return "video/mp4";
  return "image/jpeg";
}

function nextNDatesUTC(count, hour, minute) {
  const out = [];
  let d = new Date();
  for (let i = 0; i < count; i++) {
    d = new Date(d.getFullYear(), d.getMonth(), d.getDate() + 1, hour, minute, 0, 0);
    out.push(new Date(d));
  }
  return out;
}

const scheduleDates = nextNDatesUTC(inputs.length, SCHEDULE_HOUR, SCHEDULE_MIN);

// --- Build one scheduled post per input item ---
const results = inputs.map((item, idx) => {
  const j = item.json || {};

  // Prefer Cloudinary-enhanced URL chain
  const url =
    safeString(j.used_url) ||
    safeString(j.enhanced_url) ||
    safeString(j.secure_url) ||
    safeString(j?.selected_image?.url) ||
    safeString(j.url);

  if (!url) {
    throw new Error(`Missing image URL on item #${idx + 1}. Expected used_url/enhanced_url/secure_url/selected_image.url/url`);
  }

  // File name
  const name =
    safeString(j?.selected_image?.name) ||
    baseNameFromUrl(url);

  // Caption (caption → fallback derived name)
  const rawCaption =
    safeString(j.caption) ||
    `Fresh from The Avo Shack: ${safeString(name).replace(/\.[^/.]+$/, "")}`;

  const caption = stripEmojis(rawCaption).trim();

  // Schedule date
  const scheduleDate = scheduleDates[idx]
    ? scheduleDates[idx].toISOString()
    : new Date().toISOString();

  return {
    json: {
      accountIds: ACCOUNT_IDS,    // ← USING YOUR SECOND CODE'S ACCOUNTS
      summary: caption,
      media: [
        {
          url,
          type: mimeFromNameOrUrl(name || url)
        }
      ],
      type: "post",
      status: "scheduled",
      scheduleDate,
      userId: USER_ID,
      mediaOptimization: true
    }
  };
});

return results;

return items.map(item => {
  const originalUrl = item.json.secure_url || "";
  const transformations = "e_auto_color,e_auto_contrast,e_sharpen:50,e_improve";

  let enhancedUrl = originalUrl;

  // ✅ Check if Cloudinary URL & not already enhanced
  if (originalUrl.includes("/upload/") && !originalUrl.includes("e_auto_color")) {
    enhancedUrl = originalUrl.replace(
      "/upload/",
      `/upload/${transformations}/`
    );
  }

  return {
    json: {
      secure_url: originalUrl,        // Original Cloudinary URL
      enhanced_url: enhancedUrl,      // Enhanced if needed
      used_url: enhancedUrl || originalUrl // Always safe to use
    }
  };
});

// Get all input items (from Google Drive list)
const inputs = $input.all();

// Filter valid image files (must have id + name)
const imageItems = inputs.filter(i => i.json.id && i.json.name);

// If fewer than 30 images, stop
if (imageItems.length < 30) {
  throw new Error(`Need at least 30 images, found ${imageItems.length}`);
}

// Shuffle + pick 30
function pickRandom(arr, n) {
  const copy = [...arr];
  for (let i = copy.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy.slice(0, n);
}

const selected = pickRandom(imageItems, 30);

// Output selected images in expected structure for next node
return selected.map(item => {
  const imageUrl = `https://drive.google.com/uc?id=${item.json.id}`;
  return {
    json: {
      selected_image: {
        id: item.json.id,
        name: item.json.name,
        url: imageUrl
      }
    }
  };
});
